/// <summary>
/// Extension of the form <f>AVAFPLLedgerAllocationRequest</f>
/// </summary>
[ExtensionOf(formStr(AVAFPLLedgerAllocationRequest))]
internal final class AVAFPLLedgerAllocationRequestFrm_Extension
{
}

Method.Source:
/// <summary>
/// Initializes the <c>LedgerAllocationRequest</c> class.
/// </summary>
protected void initializeLedgerAllocationRequest()
{
    next initializeLedgerAllocationRequest();

    FormCheckBoxControl fCopyToCostAllocationJournal = this.design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, AVACopyToCostAllocationJournal));
    FormCheckBoxControl fPostCostAllocationJournal = this.design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, AVAPostCostAllocationJournal));
    FormCheckBoxControl fSummarizeValues = this.design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, AVASummarizeValues));
    FormCheckBoxControl fRuleArc = this.design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, AVARuleArc));

    ledgerAllocationRequest.parmCopiedWithDifLayer_bec(fCopyToCostAllocationJournal.checked());
    ledgerAllocationRequest.parmPostedWithDifLayer_bec(fPostCostAllocationJournal.checked());
    ledgerAllocationRequest.parmSummarizeValues_bec(fSummarizeValues.checked());
    ledgerAllocationRequest.parmRuleArc_bec(fRuleArc.checked());
}

/// <summary>
/// Extension of the init method
/// </summary>
public void init()
{
    next init();
    FormGroupControl fBEC_CopyPostProposal = this.design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, AVACopyPostProposal));
    fBEC_CopyPostProposal.visible(LedgerParameters::find().AVAKoRe);

    if (LedgerParameters::find().AVAKoRe)
    {
        FormCheckBoxControl fCopyToCostAllocationJournal = this.design().controlName(formControlStr(LedgerAllocationRequest, AVACopyToCostAllocationJournal));
        FormCheckBoxControl fPostCostAllocationJournal = this.design().controlName(formControlStr(LedgerAllocationRequest, AVAPostCostAllocationJournal));
        FormCheckBoxControl fSummarizeValues = this.design().controlName(formControlStr(LedgerAllocationRequest, AVASummarizeValues));
        FormComboBoxControl editProcessOptions_bec = this.design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, editProcessOptions));
        fCopyToCostAllocationJournal.checked(true);
        fPostCostAllocationJournal.checked(true);
        fSummarizeValues.checked(true);
        fCopyToCostAllocationJournal.enabled(true);
        fPostCostAllocationJournal.enabled(true);
        fSummarizeValues.enabled(true);
        editProcessOptions_bec.selection(LedgerAllocationProcessMode::ProposalOnly);
        editProcessOptions_bec.enabled(false);

    }
}
